 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            cells = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny,nx) not in seen:
                        seen.add((ny,nx)); stack.append((ny,nx))
            markers = [(y,x,grid[y][x]) for y,x in cells if grid[y][x] not in (0,1)]
            comps.append((cells,markers))
    marked = [(cells,markers) for cells,markers in comps if markers]
    for cells, markers in comps:
        if not markers:
            if not marked: continue
            # nearest marked object's cells by Manhattan distance
            dist, chosen = min((min(abs(y-a)+abs(x-b) for y,x in cells for a,b,_ in mc), mc)
                              for cc, mc in marked for y,x in [(0,0)])
            # compute distance correctly using component cell positions
            best = None
            for mcells, mmarkers in marked:
                d = min(abs(y-a)+abs(x-b) for y,x in cells for a,b in mcells)
                colset = {m[2] for m in mmarkers}
                col = min(colset)
                cand = (d, col, mcells, mmarkers)
                if best is None or cand[:2] < best[:2]: best = cand
            markers = best[3]
        # nearest seed color within this object for each eligible cell
        for y,x in cells:
            if grid[y][x] != 1 or not all(0 <= y+dy < h and 0 <= x+dx < w and grid[y+dy][x+dx] != 0 for dy in (-1,0,1) for dx in (-1,0,1)):
                continue
            out[y][x] = min(markers, key=lambda m: (abs(y-m[0])+abs(x-m[1]), m[2], m[0], m[1]))[2]
    return out
